51	/**
52	 * Global Exception handler for REST controllers.
53	 * <p>
54	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
55	 *
56	 * @author Vitaliy Fedoriv
57	 * @author Alexander Dudkin
58	 */
59	@ControllerAdvice
60	public class ExceptionControllerAdvice {
61	
62	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
63	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
64	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
65	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
66	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
67	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
68	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
69	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
70	    private static final String ERROR_INVALID_EMAIL = "The request contains an invalid email address";
71	    private static final String ERROR_INVALID_POSTCODE = "The request contains a postcode that is not valid for the owner's city";
72	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
73	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
74	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The request contains a registration date later than the server date";
75	
76	    /**
77	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
78	     * class.
79	     *
80	     * @param e     Object referring to the thrown exception.
81	     * @param status HTTP response status.
82	     * @param url URL request.
83	     */
84	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
85	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
86	        problemDetail.setType(URI.create(url.toString()));
87	        problemDetail.setTitle(e.getClass().getSimpleName());
88	        problemDetail.setDetail(detail);
89	        problemDetail.setProperty("timestamp", Instant.now());
90	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
91	        return problemDetail;
92	    }
93	
94	    /**
95	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
96	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
97	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
98	     * would catch it and report an authorization failure as a 500.
99	     *
100	     * @param e The {@link AccessDeniedException} to propagate
101	     * @throws AccessDeniedException always
102	     */
103	    @ExceptionHandler(AccessDeniedException.class)
104	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
105	        throw e;
106	    }
107	
108	    /**
109	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
110	     *
111	     * @param e The {@link Exception} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
114	     */
115	    @ExceptionHandler(Exception.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
118	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
119	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
120	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
121	        return ResponseEntity.status(status).body(detail);
122	    }
123	
124	    /**
125	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
126	     * method returns a 404 Not Found status if an entity does not exist.
127	     *
128	     * @param e The {@link DataIntegrityViolationException} to be handled
129	     * @param request {@link HttpServletRequest} object referring to the current request.
130	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
131	     */
132	    @ExceptionHandler(DataIntegrityViolationException.class)
133	    @ResponseBody
134	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
135	        logger.warn("Data integrity violation at {} {}: {}",
136	            request.getMethod(),
137	            request.getRequestURI(),
138	            e.getMessage());
139	        logger.debug("Data integrity violation stacktrace", e);
140	        HttpStatus status = HttpStatus.NOT_FOUND;
141	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
142	        return ResponseEntity.status(status).body(detail);
143	    }
144	
145	    /**
146	     * Handles exception thrown by Bean Validation on controller methods parameters
147	     *
148	     * @param e The {@link MethodArgumentNotValidException} to be handled
149	     * @param request {@link HttpServletRequest} object referring to the current request.
150	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
151	     */
152	    @ExceptionHandler(MethodArgumentNotValidException.class)
153	    @ResponseBody
154	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
155	        HttpStatus status = HttpStatus.BAD_REQUEST;
156	        BindingErrorsResponse errors = new BindingErrorsResponse();
157	        BindingResult bindingResult = e.getBindingResult();
158	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
159	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
160	            .map(FieldError::getField)
161	            .distinct()
162	            .toList();
163	        detail.setProperty("errors", invalidFields);
164	        if (bindingResult.hasErrors()) {
165	            errors.addAllErrors(bindingResult);
166	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
167	                .map(fieldError -> {
168	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
169	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
170	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
171	                        fieldError.getField(),
172	                        defaultMessage,
173	                        rejectedValue);
174	                    return new ValidationMessageDto(message)
175	                        .putAdditionalProperty("field", fieldError.getField())
176	                        .putAdditionalProperty("rejectedValue", rejectedValue)
177	                        .putAdditionalProperty("defaultMessage", defaultMessage);
178	                })
179	                .toList();
180	            logger.debug("Validation error at {} {}: {}",
181	                request.getMethod(),
182	                request.getRequestURI(),
183	                bindingResult.getFieldErrors());
184	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
185	            return ResponseEntity.status(status).body(detail);
186	        }
187	        return ResponseEntity.status(status).body(detail);
188	    }
189	
190	    /**
191	     * Handles {@link RequiredFieldsMissingException} raised when a request omits or blanks
192	     * out mandatory fields. Returns a 400 Bad Request whose body carries an {@code errors}
193	     * array listing the name of each offending field.
194	     *
195	     * @param e The {@link RequiredFieldsMissingException} to be handled
196	     * @param request {@link HttpServletRequest} object referring to the current request.
197	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
198	     */
199	    @ExceptionHandler(RequiredFieldsMissingException.class)
200	    @ResponseBody
201	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
202	        HttpStatus status = HttpStatus.BAD_REQUEST;
203	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
204	        detail.setProperty("errors", e.getFields());
205	        logger.debug("Missing required fields at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getFields());
209	        return ResponseEntity.status(status).body(detail);
210	    }
