212	    /**
213	     * Handles {@link DuplicateTelephoneException} raised when a create request supplies a
214	     * normalized telephone already used by another owner. Returns a 409 Conflict whose body
215	     * carries an {@code errors} array naming the {@code telephone} field.
216	     *
217	     * @param e The {@link DuplicateTelephoneException} to be handled
218	     * @param request {@link HttpServletRequest} object referring to the current request.
219	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
220	     */
221	    /**
222	     * Handles {@link InvalidEmailException} raised when a create or update request supplies an
223	     * {@code email} that is present but not a syntactically valid address. Returns a 400 Bad
224	     * Request whose body carries an {@code errors} array naming the {@code email} field.
225	     *
226	     * @param e The {@link InvalidEmailException} to be handled
227	     * @param request {@link HttpServletRequest} object referring to the current request.
228	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
229	     */
230	    @ExceptionHandler(InvalidEmailException.class)
231	    @ResponseBody
232	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
233	        HttpStatus status = HttpStatus.BAD_REQUEST;
234	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_EMAIL);
235	        detail.setProperty("errors", List.of("email"));
236	        logger.debug("Invalid email at {} {}: {}",
237	            request.getMethod(),
238	            request.getRequestURI(),
239	            e.getEmail());
240	        return ResponseEntity.status(status).body(detail);
241	    }
242	
243	    /**
244	     * Handles {@link InvalidPostcodeException} raised when a create request supplies a
245	     * {@code postcode} that is present but out of range for the owner's city's region. Returns a
246	     * 400 Bad Request whose body carries an {@code errors} array naming the {@code postcode} field.
247	     *
248	     * @param e The {@link InvalidPostcodeException} to be handled
249	     * @param request {@link HttpServletRequest} object referring to the current request.
250	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
251	     */
252	    @ExceptionHandler(InvalidPostcodeException.class)
253	    @ResponseBody
254	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
255	        HttpStatus status = HttpStatus.BAD_REQUEST;
256	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_POSTCODE);
257	        detail.setProperty("errors", List.of("postcode"));
258	        logger.debug("Invalid postcode at {} {}: {}",
259	            request.getMethod(),
260	            request.getRequestURI(),
261	            e.getPostcode());
262	        return ResponseEntity.status(status).body(detail);
263	    }
264	
265	    /**
266	     * Handles {@link DuplicateEmailException} raised when a create request supplies an
267	     * {@code email} whose lower-cased form is already used by another owner. Returns a 409
268	     * Conflict whose body carries an {@code errors} array naming the {@code email} field.
269	     *
270	     * @param e The {@link DuplicateEmailException} to be handled
271	     * @param request {@link HttpServletRequest} object referring to the current request.
272	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
273	     */
274	    @ExceptionHandler(DuplicateEmailException.class)
275	    @ResponseBody
276	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
277	        HttpStatus status = HttpStatus.CONFLICT;
278	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_EMAIL);
279	        detail.setProperty("errors", List.of("email"));
280	        logger.debug("Duplicate email at {} {}: {}",
281	            request.getMethod(),
282	            request.getRequestURI(),
283	            e.getEmail());
284	        return ResponseEntity.status(status).body(detail);
285	    }
286	
287	    /**
288	     * Handles {@link DuplicateIdentityException} raised when a create request supplies an owner
289	     * whose whole derived {@code identityKey} already equals that of an existing owner. This one
290	     * key consolidates the former telephone, email and household duplicate checks. Returns a 409
291	     * Conflict whose body carries an {@code errors} array naming the {@code identityKey} field.
292	     *
293	     * @param e The {@link DuplicateIdentityException} to be handled
294	     * @param request {@link HttpServletRequest} object referring to the current request.
295	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
296	     */
297	    @ExceptionHandler(DuplicateIdentityException.class)
298	    @ResponseBody
299	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
300	        HttpStatus status = HttpStatus.CONFLICT;
301	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
302	        detail.setProperty("errors", List.of("identityKey"));
303	        logger.debug("Duplicate identity at {} {}: {}",
304	            request.getMethod(),
305	            request.getRequestURI(),
306	            e.getIdentityKey());
307	        return ResponseEntity.status(status).body(detail);
308	    }
309	
310	    @ExceptionHandler(DuplicateTelephoneException.class)
311	    @ResponseBody
312	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
313	        HttpStatus status = HttpStatus.CONFLICT;
314	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
315	        detail.setProperty("errors", List.of("telephone"));
316	        logger.debug("Duplicate telephone at {} {}: {}",
317	            request.getMethod(),
318	            request.getRequestURI(),
319	            e.getTelephone());
320	        return ResponseEntity.status(status).body(detail);
321	    }
322	
323	    /**
324	     * Handles {@link DuplicateHouseholdException} raised when a create request supplies a
325	     * last name and address already used by another owner (compared case-insensitively with
326	     * collapsed whitespace) without opting in via {@code sharesHousehold}. Returns a 409
327	     * Conflict whose body carries an {@code errors} array naming the {@code lastName} and
328	     * {@code address} fields.
329	     *
330	     * @param e The {@link DuplicateHouseholdException} to be handled
331	     * @param request {@link HttpServletRequest} object referring to the current request.
332	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
333	     */
334	    @ExceptionHandler(DuplicateHouseholdException.class)
335	    @ResponseBody
