337	        HttpStatus status = HttpStatus.CONFLICT;
338	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
339	        detail.setProperty("errors", List.of("lastName", "address"));
340	        logger.debug("Duplicate household at {} {}: {} / {}",
341	            request.getMethod(),
342	            request.getRequestURI(),
343	            e.getLastName(),
344	            e.getAddress());
345	        return ResponseEntity.status(status).body(detail);
346	    }
